from openai_harmony import (
    load_harmony_encoding, HarmonyEncodingName, Conversation, Message, Role, SystemContent,
    DeveloperContent, ReasoningEffort, ToolDescription
) 

# Load the encoding
encoding = load_harmony_encoding(HarmonyEncodingName.HARMONY_GPT_OSS)

def convert_to_harmony_string(msg, ai_response=None, model_identity=None, function_object=None, reasoning_level=ReasoningEffort.MEDIUM,
                             channels = ["analysis"]):

    messages=[
        Message.from_role_and_content(
            Role.SYSTEM,
            SystemContent.new()
                .with_model_identity(model_identity if model_identity else "You are an helpful AI assistant.")
                .with_knowledge_cutoff("2025-08")
                .with_reasoning_effort(reasoning_level)
                .with_required_channels(channels)
                # .with_browser_tool()
                # .with_python_tool()
        ),
    ]
    if function_object:messages.append(function_object)
    messages.append(
        Message.from_role_and_content(Role.USER, msg)
    )
    if ai_response: messages.append(Message.from_role_and_content(Role.ASSISTANT, ai_response))
    convo = Conversation.from_messages(messages)
    
    harmony_tokens = encoding.render_conversation_for_completion(convo, Role.ASSISTANT)
    
    harmony_text = encoding.decode(harmony_tokens)
    if ai_response: return harmony_text[:-18]
    return harmony_text

